<?php $draft=$payment['status']==='draft';?><div class="page-header mb-4"><div class="row"><div class="col"><h2 class="page-title"><?=e($payment['payment_code'])?></h2></div><div class="col-auto d-flex gap-2"><a class="btn" href="/supplier-payments">العودة</a><?php if($payment['status']==='posted'):?><a class="btn" href="/supplier-payments/<?=(int)$payment['id']?>/print">طباعة</a><?php endif;?><?php if($draft&&$canEdit):?><a class="btn" href="/supplier-payments/<?=(int)$payment['id']?>/edit">تعديل</a><?php endif;?></div></div></div><div class="row g-3 mb-4"><?php foreach(['invoice_total'=>'إجمالي الفاتورة','paid'=>'المدفوع','remaining'=>'المتبقي']as$k=>$l):?><div class="col-md-4"><div class="card"><div class="card-body"><div class="text-secondary"><?=$l?></div><div class="h2"><?=e($summary[$k])?></div></div></div></div><?php endforeach;?></div><div class="card mb-4"><div class="card-body"><div class="row g-3"><?php foreach(['payment_date'=>'تاريخ الدفع','amount'=>'المبلغ','payment_method'=>'طريقة الدفع','reference'=>'المرجع','invoice_code'=>'الفاتورة','vendor_name'=>'المورد','project_name'=>'المشروع','status'=>'الحالة']as$k=>$l):?><div class="col-md-3"><div class="text-secondary"><?=$l?></div><strong><?=e($payment[$k]??'—')?></strong></div><?php endforeach;?></div></div></div><?php if($draft):?><div class="d-flex gap-2"><?php if($canPost):?><form method="post" action="/supplier-payments/<?=(int)$payment['id']?>/post" class="js-confirm-form"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-success">ترحيل الدفعة</button></form><?php endif;?><?php if($canCancel):?><form method="post" action="/supplier-payments/<?=(int)$payment['id']?>/cancel" class="js-confirm-form"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-danger">إلغاء المسودة</button></form><?php endif;?></div><?php endif;?>
